// Browser-only imitation for synthetic local previews. Production raster pages
// are generated by the authenticated server and never use this adapter.
import pdfWorkerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url'
import type { PDFDocumentProxy, PDFDocumentLoadingTask } from 'pdfjs-dist'
import type { TeachingMaterialFileInfo } from './teachingMaterialPreview'

type Source = { kind: 'pdf'; pdf: PDFDocumentProxy; task: PDFDocumentLoadingTask; pages: number } | { kind: 'image'; bitmap: ImageBitmap; pages: number } | { kind: 'text'; lines: string[]; pages: number }
const sources = new Map<string, Promise<Source>>()
const TEXT_LINES = 45
const LIMIT_PAGES = 1000

async function source(url: string, info: Pick<TeachingMaterialFileInfo, 'preview_kind' | 'version' | 'size'>): Promise<Source> {
  if (!url.startsWith('blob:')) throw new Error('Локальний приклад працює тільки з файлами, доданими у цьому браузері.')
  const key = url + ':' + info.version
  const known = sources.get(key)
  if (known) return known
  const load = (async (): Promise<Source> => {
    const response = await fetch(url)
    const data = await response.arrayBuffer()
    if (data.byteLength !== info.size || data.byteLength > 50 * 1024 * 1024) throw new Error('Локальний файл змінився.')
    if (info.preview_kind === 'pdf') {
      const pdfjs = await import('pdfjs-dist')
      pdfjs.GlobalWorkerOptions.workerSrc = pdfWorkerUrl
      const pdfOptions = { data: new Uint8Array(data), isEvalSupported: false, enableXfa: false, useWorkerFetch: false, useWasm: false, useSystemFonts: true, stopAtErrors: true }
      const task = pdfjs.getDocument(pdfOptions)
      task.onPassword = () => { void task.destroy().catch(() => {}) }
      const pdf = await task.promise
      if (pdf.numPages > LIMIT_PAGES) { await task.destroy(); throw new Error('У локальному прикладі можна відкрити до 1000 сторінок.') }
      return { kind: 'pdf', pdf, task, pages: pdf.numPages }
    }
    if (info.preview_kind === 'image') {
      const bitmap = await createImageBitmap(new Blob([data]))
      if (bitmap.width * bitmap.height > 32_000_000) { bitmap.close(); throw new Error('Зображення завелике для локального перегляду.') }
      return { kind: 'image', bitmap, pages: 1 }
    }
    const text = new TextDecoder().decode(data).replace(/\u0000/g, '')
    const lines: string[] = []
    for (const line of text.split(/\r?\n/)) {
      if (!line.length) lines.push('')
      for (let start = 0; start < line.length; start += 90) {
        lines.push(line.slice(start, start + 90))
        if (lines.length > LIMIT_PAGES * TEXT_LINES) throw new Error('Текст завеликий для локального посторінкового перегляду.')
      }
    }
    return { kind: 'text', lines, pages: Math.max(1, Math.ceil(lines.length / TEXT_LINES)) }
  })()
  sources.set(key, load)
  load.catch(() => { if (sources.get(key) === load) sources.delete(key) })
  // Preview-only cache: keep at most the most recently opened documents.
  if (sources.size > 2) {
    const oldest = sources.keys().next().value!
    const old = sources.get(oldest)!
    sources.delete(oldest)
    void old.then(value => { if (value.kind === 'pdf') return value.task.destroy(); if (value.kind === 'image') value.bitmap.close() }).catch(() => {})
  }
  return load
}

export async function localMaterialRasterPageCount(url: string, info: Pick<TeachingMaterialFileInfo, 'preview_kind' | 'version' | 'size'>) {
  return (await source(url, info)).pages
}

export async function localMaterialRasterPage(url: string, info: TeachingMaterialFileInfo, page: number, signal?: AbortSignal): Promise<ArrayBuffer> {
  signal?.throwIfAborted()
  const documentSource = await source(url, info)
  if (!Number.isSafeInteger(page) || page < 1 || page > documentSource.pages) throw new Error('Цієї сторінки немає.')
  signal?.throwIfAborted()
  const canvas = document.createElement('canvas')
  const scaleFor = (width: number, height: number) => Math.min(2000 / Math.max(width, height), Math.sqrt(3_000_000 / (width * height)))
  if (documentSource.kind === 'pdf') {
    const pdfPage = await documentSource.pdf.getPage(page)
    const size = pdfPage.getViewport({ scale: 1 })
    const viewport = pdfPage.getViewport({ scale: scaleFor(size.width, size.height) })
    canvas.width = Math.max(1, Math.floor(viewport.width)); canvas.height = Math.max(1, Math.floor(viewport.height))
    await pdfPage.render({ canvas, viewport, background: '#ffffff' }).promise
  } else {
    if (documentSource.kind === 'image') {
      const scale = scaleFor(documentSource.bitmap.width, documentSource.bitmap.height)
      canvas.width = Math.max(1, Math.floor(documentSource.bitmap.width * scale)); canvas.height = Math.max(1, Math.floor(documentSource.bitmap.height * scale))
    } else { canvas.width = 1400; canvas.height = 1900 }
    const context = canvas.getContext('2d')!
    context.fillStyle = '#ffffff'; context.fillRect(0, 0, canvas.width, canvas.height)
    if (documentSource.kind === 'image') context.drawImage(documentSource.bitmap, 0, 0, canvas.width, canvas.height)
    else {
      context.fillStyle = '#111827'; context.font = '22px monospace'
      documentSource.lines.slice((page - 1) * TEXT_LINES, page * TEXT_LINES).forEach((line, index) => context.fillText(line, 45, 70 + index * 37, canvas.width - 90))
    }
  }
  signal?.throwIfAborted()
  const context = canvas.getContext('2d')!
  const viewer = info.viewer_name.trim().slice(0, 120) || 'Учасник групи'
  context.save(); context.globalAlpha = 0.22; context.fillStyle = '#1e3a5f'
  context.font = '600 25px sans-serif'; context.rotate(-Math.PI / 9)
  for (let y = -canvas.width; y < canvas.height * 1.5; y += 190)
    for (let x = -canvas.width; x < canvas.width * 1.5; x += 700) context.fillText(viewer, x, y, 650)
  context.restore()
  context.fillStyle = '#ffffff'; context.fillRect(0, canvas.height - 42, canvas.width, 42)
  context.fillStyle = '#374151'; context.font = '18px sans-serif'
  context.fillText(viewer + ' · ' + info.author_name.slice(0, 120) + ' · ' + page + '/' + documentSource.pages, 16, canvas.height - 14, canvas.width - 32)
  const blob = await new Promise<Blob>((resolve, reject) => canvas.toBlob(value => value ? resolve(value) : reject(new Error('Не вдалося підготувати локальну сторінку.')), 'image/webp', 0.9))
  signal?.throwIfAborted()
  return blob.arrayBuffer()
}
